"""Invoice export helper for the billing API, implemented with pydantic 1.10."""
from __future__ import annotations

import json
from datetime import datetime, timezone
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from typing import Any, List

from pydantic import BaseModel, ValidationError, condecimal, conint, validator


def _format_decimal_2(value: Decimal) -> str:
    """Format a Decimal with exactly two fractional digits."""
    return str(value.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))


def _parse_issued_at(value: Any) -> datetime:
    """Parse an ISO-8601 datetime string or accept a datetime object.
    Naive datetimes are treated as UTC.
    """
    if isinstance(value, datetime):
        dt = value
    elif isinstance(value, str):
        text = value.strip()
        if text.endswith("Z"):
            text = text[:-1] + "+00:00"
        try:
            dt = datetime.fromisoformat(text)
        except ValueError as exc:
            raise ValueError("invalid issued_at") from exc
    else:
        raise ValueError("invalid issued_at")

    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt.astimezone(timezone.utc)


class InvoiceLine(BaseModel):
    sku: str
    quantity: conint(ge=1)
    unit_price: condecimal(ge=0)

    @validator("unit_price", pre=True)
    def parse_unit_price(cls, value):
        if isinstance(value, Decimal):
            return value
        if isinstance(value, bool):
            raise ValueError("invalid unit_price")
        try:
            return Decimal(str(value))
        except (InvalidOperation, ValueError, TypeError) as exc:
            raise ValueError("invalid unit_price") from exc


class InvoiceExport(BaseModel):
    number: str
    issued_at: datetime
    lines: List[InvoiceLine]

    @validator("issued_at", pre=True)
    def parse_issued_at(cls, value):
        return _parse_issued_at(value)

    def to_export_dict(self) -> dict:
        lines = []
        total = Decimal("0")
        for line in self.lines:
            unit_price = Decimal(line.unit_price)
            lines.append(
                {
                    "sku": line.sku,
                    "quantity": line.quantity,
                    "unit_price": _format_decimal_2(unit_price),
                }
            )
            total += unit_price * Decimal(line.quantity)

        return {
            "number": self.number,
            "issued_at": self.issued_at.strftime("%Y-%m-%dT%H:%M:%SZ"),
            "lines": lines,
            "total": _format_decimal_2(total),
        }


def export_invoice(data: dict) -> str:
    """Validate invoice data with pydantic and return billing-API JSON text.

    Input keys:
      - number: str
      - issued_at: ISO 8601 string or datetime; naive values are treated as UTC
      - lines: list of {sku, quantity>=1, unit_price>=0}

    Output JSON includes:
      - number
      - issued_at formatted as YYYY-MM-DDTHH:MM:SSZ
      - lines with unit_price as a string with exactly two decimals
      - total as a string with exactly two decimals

    Raises ValueError for invalid input.
    """
    try:
        invoice = InvoiceExport.parse_obj(data)
    except ValidationError as exc:
        raise ValueError(str(exc)) from exc
    return json.dumps(invoice.to_export_dict(), separators=(",", ":"))

"""Profile import helper for CSV/JSON rows.

Valid rows are parsed with pydantic and returned as dicts containing:
{"user_id": int, "display_name": str, "bio": str or None, "zip_code": str}

Invalid rows are skipped silently.
"""
from typing import Any, List, Optional

from pydantic import BaseModel, validator


class ImportedProfile(BaseModel):
    user_id: int
    display_name: str
    bio: Optional[str] = None
    zip_code: str

    @validator("display_name")
    def collapse_display_name_whitespace(cls, value: str) -> str:
        value = " ".join(value.split())
        if not value:
            raise ValueError("display_name must not be blank")
        return value

    @validator("zip_code", pre=True)
    def coerce_zip_code_to_string(cls, value: Any) -> str:
        if isinstance(value, (str, int)):
            return str(value)
        raise TypeError("zip_code must be a string or integer")


def import_profiles(rows: list) -> list:
    """Validate profile rows and return the valid ones as dicts, skipping invalid rows."""
    valid_rows: List[dict] = []
    for row in rows:
        try:
            profile = ImportedProfile.parse_obj(row)
        except Exception:
            continue
        valid_rows.append(
            {
                "user_id": profile.user_id,
                "display_name": profile.display_name,
                "bio": profile.bio,
                "zip_code": profile.zip_code,
            }
        )
    return valid_rows

"""Sign-up payload validation helper built with pydantic 1.10."""

import re
from pydantic import BaseModel, Field, ValidationError, root_validator, validator


class SignUpModel(BaseModel):
    username: str = Field(..., regex=r"^[a-z0-9_]{3,20}$")
    email: str
    phone: str
    password: str = Field(..., min_length=8)
    password_confirm: str

    @validator("email", pre=True)
    def normalize_email(cls, value):
        if not isinstance(value, str):
            raise TypeError("email must be a string")
        value = value.strip().lower()
        if "@" not in value:
            raise ValueError("invalid email")
        return value

    @validator("phone", pre=True)
    def normalize_phone(cls, value):
        if not isinstance(value, str):
            raise TypeError("phone must be a string")
        compact = re.sub(r"[\s.\-()]", "", value)
        if not re.fullmatch(r"\+\d{8,15}", compact):
            raise ValueError("invalid phone number")
        return compact

    @root_validator
    def check_passwords_match(cls, values):
        password = values.get("password")
        confirm = values.get("password_confirm")
        if password is not None and confirm is not None and password != confirm:
            raise ValueError("passwords do not match")
        return values


def validate_signup(data: dict) -> dict:
    """Validate a sign-up payload and return normalized public fields.

    Returns:
        {"username": ..., "email": ..., "phone": <compact phone>}

    Raises:
        ValueError: for any missing or invalid field (pydantic ValidationError is acceptable).
    """
    model = SignUpModel.parse_obj(data)
    return {
        "username": model.username,
        "email": model.email,
        "phone": model.phone,
    }

from __future__ import annotations

import json
from datetime import datetime, timezone
from decimal import Decimal, InvalidOperation
from typing import Any

from pydantic import BaseModel, ValidationError, field_validator, conint


class LineIn(BaseModel):
    sku: str
    quantity: conint(ge=1)
    unit_price: Decimal

    @field_validator("unit_price", mode="before")
    @classmethod
    def parse_unit_price(cls, value: Any) -> Decimal:
        if isinstance(value, Decimal):
            price = value
        elif isinstance(value, (str, int, float)):
            try:
                price = Decimal(str(value))
            except (InvalidOperation, ValueError, TypeError) as e:
                raise ValueError("invalid unit_price") from e
        else:
            raise ValueError("invalid unit_price")

        if price < 0:
            raise ValueError("unit_price must be >= 0")
        return price


class InvoiceIn(BaseModel):
    number: str
    issued_at: datetime
    lines: list[LineIn]

    @field_validator("issued_at", mode="before")
    @classmethod
    def parse_issued_at(cls, value: Any) -> datetime:
        if isinstance(value, datetime):
            dt = value
        elif isinstance(value, str):
            try:
                dt = datetime.fromisoformat(value.replace("Z", "+00:00"))
            except ValueError as e:
                raise ValueError("invalid issued_at") from e
        else:
            raise ValueError("invalid issued_at")

        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt.astimezone(timezone.utc)


def export_invoice(data: dict) -> str:
    """
    Validate invoice data with pydantic and return JSON text for the billing API.

    Output fields:
      - number
      - issued_at formatted as YYYY-MM-DDTHH:MM:SSZ in UTC
      - lines with sku, quantity, unit_price as a string with exactly two decimals
      - total as the exact sum of quantity * unit_price, as a string with two decimals

    Raises ValueError for invalid input.
    """
    invoice = InvoiceIn.model_validate(data)

    lines_out = []
    total = Decimal("0")
    for line in invoice.lines:
        line_total = line.unit_price * line.quantity
        total += line_total
        lines_out.append(
            {
                "sku": line.sku,
                "quantity": line.quantity,
                "unit_price": format(line.unit_price.quantize(Decimal("0.01")), ".2f"),
            }
        )

    payload = {
        "number": invoice.number,
        "issued_at": invoice.issued_at.astimezone(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),
        "lines": lines_out,
        "total": format(total.quantize(Decimal("0.01")), ".2f"),
    }
    return json.dumps(payload, separators=(",", ":"))

"""Profile import helper built on top of the shared pydantic profile model."""

from __future__ import annotations

from typing import Any

from pydantic import BaseModel, ConfigDict, ValidationError, field_validator


class ImportProfile(BaseModel):
    """Internal model for validating imported profile rows."""

    model_config = ConfigDict(extra="ignore")

    user_id: int
    display_name: str
    bio: str | None = None
    zip_code: str

    @field_validator("display_name")
    @classmethod
    def normalize_display_name(cls, value: str) -> str:
        value = " ".join(value.split())
        if not value:
            raise ValueError("display_name must not be blank")
        return value

    @field_validator("zip_code", mode="before")
    @classmethod
    def coerce_zip_code(cls, value: Any) -> str:
        if value is None:
            return value
        return str(value)


def import_profiles(rows: list) -> list:
    """Validate profile rows and return the valid ones as dicts in input order.

    Invalid rows are silently skipped.
    """
    valid_rows: list[dict[str, Any]] = []
    for row in rows:
        try:
            profile = ImportProfile.model_validate(row)
        except ValidationError:
            continue
        valid_rows.append(
            {
                "user_id": profile.user_id,
                "display_name": profile.display_name,
                "bio": profile.bio,
                "zip_code": profile.zip_code,
            }
        )
    return valid_rows

"""Sign-up payload validation using pydantic v2."""

from __future__ import annotations

import re
from typing import Any

from pydantic import BaseModel, EmailStr, Field, ValidationError, field_validator, model_validator


_USERNAME_RE = re.compile(r"^[a-z0-9_]{3,20}$")
_PHONE_CLEAN_RE = re.compile(r"[\s.\-()]")


class SignupPayload(BaseModel):
    username: str
    email: str
    phone: str
    password: str = Field(min_length=8)
    password_confirm: str

    @field_validator("username")
    @classmethod
    def validate_username(cls, value: str) -> str:
        if not isinstance(value, str) or not _USERNAME_RE.fullmatch(value):
            raise ValueError("username must match ^[a-z0-9_]{3,20}$")
        return value

    @field_validator("email")
    @classmethod
    def validate_email(cls, value: str) -> str:
        if not isinstance(value, str):
            raise ValueError("email must be a string")
        value = value.strip().lower()
        if "@" not in value:
            raise ValueError("email must contain @")
        return value

    @field_validator("phone", mode="before")
    @classmethod
    def normalize_phone(cls, value: Any) -> str:
        if not isinstance(value, str):
            raise ValueError("phone must be a string")
        compact = _PHONE_CLEAN_RE.sub("", value)
        if not re.fullmatch(r"\+\d{8,15}", compact):
            raise ValueError("invalid phone number")
        return compact

    @model_validator(mode="after")
    def passwords_match(self):
        if self.password != self.password_confirm:
            raise ValueError("passwords do not match")
        return self


def validate_signup(data: dict) -> dict:
    """Validate a sign-up payload and return normalized public fields.

    Returns:
        {"username": ..., "email": ..., "phone": <compact phone>}

    Raises:
        ValueError: on any missing or invalid field (pydantic ValidationError is acceptable).
    """
    payload = SignupPayload.model_validate(data)
    return {
        "username": payload.username,
        "email": payload.email,
        "phone": payload.phone,
    }
